// BLOCKED SCAFFOLD -- see workflow meta.description. This mirrors sm-rank-pull.json's
// due-check shape for tool_scope.volume, EXCEPT there is no real signal to check a 'last
// fetched' timestamp against (no listing tool exposes search_keywords.metrics_fetched_at as a
// rollup), so this uses workflowStaticData as a STAND-IN only -- explicitly NOT the shipped
// idempotency story (n8n-local memory is exactly the anti-pattern SM-15's own rules warn
// against relying on). Once the platform exposes a real per-engagement 'last metrics pull'
// signal, replace this with the same platform-truth pattern sm-rank-pull.json uses.
const hubUrl = 'http://mcp-hub:3003/mcp';
const tenantId = $env.AGENCY_TENANT_ID;
const workflowId = 'wf:sm-keyword-refresh';

const callTool = async (name, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: hubUrl,
    headers: {
      Authorization: `Bearer ${$env.HUB_SERVICE_TOKEN}`,
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
      'x-obo-provider': 'n8n',
      'x-obo-external-id': workflowId,
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args } }),
  });
  const raw = typeof res === 'string' ? res : (res?.data ?? res?.body ?? JSON.stringify(res));
  const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
  if (!line) throw new Error(`${name}: no SSE data line in hub reply: ${String(raw).slice(0, 200)}`);
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? `${name} failed`);
  return JSON.parse(rpc.result?.content?.[0]?.text ?? 'null');
};

const CADENCE_DAYS = { daily: 1, weekly: 7, monthly: 30 };
const store = $getWorkflowStaticData('global');
store.lastAttempt = store.lastAttempt || {};

const engagements = await callTool('search.listEngagements', { tenantId });
const candidates = (Array.isArray(engagements) ? engagements : [])
  .filter((e) => e.status === 'active')
  .filter((e) => e.toolScope?.volume?.enabled === true);

const due = [];
for (const eng of candidates) {
  const cadence = eng.toolScope?.volume?.cadence ?? 'monthly';
  const intervalDays = CADENCE_DAYS[cadence] ?? CADENCE_DAYS.monthly;
  const lastAt = store.lastAttempt[eng.id];
  const ageDays = lastAt ? (Date.now() - lastAt) / 86400000 : Infinity;
  if (ageDays >= intervalDays) due.push({ json: { tenantId, engagementId: eng.id, cadence } });
}
return due;

// No aggressive retry on failure (SM-50 posture, same as sm-rank-pull.json): the next
// scheduled tick is the only retry. On success, remember the attempt time in static data (the
// stand-in due-check above reads it) -- again, a scaffold behavior, not the target idempotency
// story once a real platform signal exists.
const due = $('Compute due engagements (stand-in due-check)').item.json;
const raw = $input.item.json.data ?? $input.item.json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
let result;
if (!line) { result = { ok: false, error: 'no SSE data line in hub reply' }; }
else {
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.result?.isError) result = { ok: false, error: rpc.result.content?.[0]?.text ?? 'search.keywordResearch failed (expected -- tool not registered yet)' };
  else { const store = $getWorkflowStaticData('global'); store.lastAttempt = store.lastAttempt || {}; store.lastAttempt[due.engagementId] = Date.now(); result = { ok: true, ...JSON.parse(rpc.result?.content?.[0]?.text ?? '{}') }; }
}
return [{ json: { ...due, ...result } }];
